package com.movieticket.user;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.web.bind.annotation.*;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository repo;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(12);private final SecretKey key;public AuthController(UserRepository r,@Value("${app.jwt.secret}") String secret){repo=r;key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}
 public record Credentials(@Email @NotBlank String email,@NotBlank @Size(min=8,max=72) String password){}
 @PostMapping("/signup") public ResponseEntity<?> signup(@Valid @RequestBody Credentials b){String email=b.email().toLowerCase(Locale.ROOT).trim();if(repo.findByEmail(email).isPresent())return ResponseEntity.status(409).body(Map.of("error","Email already registered"));repo.save(new User(email,encoder.encode(b.password())));return ResponseEntity.status(201).body(Map.of("message","Signup successful","email",email));}
 @PostMapping("/signin") public ResponseEntity<?> signin(@Valid @RequestBody Credentials b){User u=repo.findByEmail(b.email().toLowerCase(Locale.ROOT).trim()).orElse(null);if(u==null||!encoder.matches(b.password(),u.getPassword()))return ResponseEntity.status(401).body(Map.of("error","Invalid email or password"));Instant now=Instant.now();String token=Jwts.builder().subject(u.getEmail()).claim("role",u.getRole()).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(7200))).signWith(key).compact();return ResponseEntity.ok(Map.of("accessToken",token,"tokenType","Bearer","expiresIn",7200));}
}
